const STRIPE_DEFAULT_266='#ffffff';
function stripeSettings266(){let c=state.common;if(typeof c.adidasStripesEnabled!=='boolean')c.adidasStripesEnabled=false;if(!/^#[0-9a-f]{6}$/i.test(c.adidasStripeColor||''))c.adidasStripeColor=STRIPE_DEFAULT_266;if(typeof c.adidasStripeLeft!=='boolean')c.adidasStripeLeft=true;if(typeof c.adidasStripeRight!=='boolean')c.adidasStripeRight=true;return c;}
const legacyOutfitView266=outfitView;
outfitView=function(){let h=legacyOutfitView266();if(state.world!=='sign')return h;let c=stripeSettings266();return h+`<section class="panel" id="adidasStripe266"><h2>ADIDAS · Ärmelstreifen (nur BLACK SIGN)</h2><div class="notice">Nur bei Adidas und ausdrücklich aktiviert. Ohne Aktivierung keine erfundenen Streifen. Die Farbe ist frei wählbar.</div><label><input type="checkbox" data-section="common" data-key="adidasStripesEnabled" ${c.adidasStripesEnabled?'checked':''}> Adidas-Ärmelstreifen aktiv</label><div class="grid"><div class="field"><label>Streifenfarbe (HEX)</label><input type="color" data-section="common" data-key="adidasStripeColor" value="${esc(c.adidasStripeColor)}"></div><label><input type="checkbox" data-section="common" data-key="adidasStripeLeft" ${c.adidasStripeLeft?'checked':''}> Linker Ärmel</label><label><input type="checkbox" data-section="common" data-key="adidasStripeRight" ${c.adidasStripeRight?'checked':''}> Rechter Ärmel</label></div><p class="hint">Aktuelle Marke: ${esc(c.brand)}. Die Einstellung bleibt beim Markenwechsel gespeichert, wird aber ausschließlich für Adidas exportiert.</p></section>`;};
function stripePrompt266(){let c=stripeSettings266();if(c.brand!=='Adidas'||!c.adidasStripesEnabled)return 'ADIDAS SLEEVE STRIPES: OFF. Do not add sleeve stripes unless separately explicitly specified by the selected outfit reference.';let sides=[c.adidasStripeLeft?'LEFT':'',c.adidasStripeRight?'RIGHT':''].filter(Boolean);return sides.length?'ADIDAS SLEEVE STRIPES: EXPLICITLY ON. Color '+c.adidasStripeColor.toUpperCase()+'. Sleeves: '+sides.join(' AND ')+'. Add authentic, physically plausible stripes ONLY on selected sleeve(s), with exactly the chosen color. Do not add stripes on unselected sleeves.':'ADIDAS SLEEVE STRIPES: OFF (no sleeves selected).';}

function sideKind(type){return /teyze|tante|großmutter/i.test(type)?'teyze':/opa|dede/i.test(type)?'opa':'profession'}
